//#region src/errors.ts
var UpstreamError = class extends Error {
	service;
	status;
	detail;
	name = "UpstreamError";
	constructor(service, status, detail, path) {
		super(`${service} ${String(status)} on ${path}: ${detail}`);
		this.service = service;
		this.status = status;
		this.detail = detail;
	}
};
var MapleStoreError = class extends Error {
	reason;
	connector;
	operation;
	cause;
	name = "MapleStoreError";
	upstream;
	constructor(reason, connector, operation, cause) {
		super(`Store "${connector}" failed during ${operation} (${reason}).`);
		this.reason = reason;
		this.connector = connector;
		this.operation = operation;
		this.cause = cause;
		this.upstream = cause instanceof UpstreamError ? cause : void 0;
	}
};
var AmbiguousPullError = class extends Error {
	pulls;
	name = "AmbiguousPullError";
	constructor(pulls) {
		super(`${String(pulls.length)} open pull requests match this preview.`);
		this.pulls = pulls;
	}
};
//#endregion
export { AmbiguousPullError, MapleStoreError, UpstreamError };
